// Transparent, deterministic agents: no external model calls or confidential data.
const cases={
manufacturing:{label:'01 · 被壓低的製造報酬',icon:'🏭',island:1,chapter:'I、II、III、V',risk:'製程與產能風險',flow:'SG 總部 → 委託 TW 製造 → 交付 NL／US 經銷',strategy:'總部要求降低製造服務費，將較多集團利潤留在總部。',business:'總部主張：需求及重大產能風險由總部控制，臺灣只執行生產，因此報酬應較低。',counter:'廠長主張：我們承擔良率與設備責任，且投入自己的製程改良，不能忽略實際貢獻。',base:[160,50,25,15,50],shift:40,affected:1,charge:'製造服務收入',docs:[['製造契約與保量條款','合約載明總部控制需求並補償預留產能；但製程品質責任由工廠承擔。','§1.60 · 合約只是起點'],['產能核准與製程決策紀錄','總部核定產量，臺灣工程師則決定重要製程改良與良率處理，並持有自有設備。','§1.65–1.66 · 控制的實際履行'],['分部損益與比較樣本','本故事假設已完成可靠 TNMM 分析：一致成本基礎 1,000，可靠常規區間為 4%–6%，例示採中位數 5%。申報淨利為 10（1%）。實際案件不得直接套用。','Ch. II、III · 受測個體及可比較性'],['企業提出的反證','總部提出景氣衰退及額外支援證據；需確認比較樣本是否也受影響、可否作可靠調整，以及有無重複計酬。','§3.47–3.54 · 差異調整']],issue:'低製造報酬是否與實際製程、設備與風險相符？若存在獨特且有價值的無形資產貢獻，TNMM 是否仍合適？',method:'本故事在已排除不可比差異、並假設 TNMM 適當的前提下，用成本基礎 × 例示淨利指標計算。',amount:40,calcBase:1000,target:5,reported:10,authority:'臺灣國稅局',taxLabel:'臺灣所得稅調整 · 稅率為可修改的教學假設',resolution:'公司主張景氣因素應調整比較結果。稽徵機關須具體回應反證，再判斷方法、樣本與區間是否仍可靠。',memory:'保留產能核准、製程責任及分部損益；下期先檢查常規區間與差異，不能只依集團預算壓低報酬。'},
royalty:{label:'02 · 專利與權利金的迷霧',icon:'💡',island:2,chapter:'I、II、VI、V',risk:'技術開發風險與 DEMPE 報酬',flow:'JP 研發 → SG 法律持有技術 → 向 JP 收取權利金',strategy:'總部提高向研發子公司收取的技術權利金，使利潤流向法律持有人。',business:'總部主張：專利登記與資金投入均由總部負責，所以應收取較多權利金。',counter:'研發主管主張：我們決定關鍵試驗並承擔開發責任，法律權利不能取代 DEMPE 分析。',base:[180,10,45,15,50],shift:20,affected:2,charge:'支付總部的權利金',docs:[['技術授權合約','總部持有法律權利，研發島支付權利金；契約本身不能解決全部報酬歸屬。','§6.32–6.42 · 法律所有權'],['實驗、人員與預算決策','關鍵試驗由日本人員設計、決定並監控；總部提供資金，技術決策能力須另查。','§6.48–6.58 · DEMPE 與控制'],['權利金比較與分部帳','本教學假設可靠分析支持減少例示權利金費用 20；這不是固定比率，且需避免與研發報酬重複調整。','Ch. II、VI · 方法及報酬'],['企業提出的反證','總部提交研發評估委員會紀錄、外部專家評估與失敗專案承擔資料；應查證是否實際決策，並重新評估貢獻。','Ch. I、VI · 完整事實']],issue:'總部是否僅出資，還是實際控制研發風險？日本的貢獻是否已由服務費充分補償？需要單邊方法還是利潤分割？',method:'此情境以已完成可靠分析的「應減列權利金費用」作例示輸入，不假設 DEMPE 必然導致全部剩餘利潤歸研發島。',amount:20,authority:'日本稅務機關（概念模擬）',taxLabel:'外國調整概念 · 程序與稅率為假設，非日本法定流程',resolution:'納稅人提出總部的實際技術控制證據後，原擬調整金額可能改變；應同時檢查服務費與權利金是否重複計酬。',memory:'預先整理 DEMPE 人員與決策圖譜；授權與研發服務定價合併檢視，避免只按專利登記分配利潤。'},
lrd:{label:'03 · LRD 的南瓜庫存危機',icon:'🎃',island:3,chapter:'I、II、III、IX',risk:'存貨跌價與市場風險',flow:'SG 晶片 → NL 有限風險經銷商 → 獨立客戶',strategy:'總部要求風車島承擔秋季滯銷晶片損失，合約卻仍寫由總部承擔跌價。',business:'總部主張：經銷商負責在地銷售，滯銷損失自然應留在當地。',counter:'經銷主管主張：備貨是總部決定的，並非我們自主承擔的風險；要查實際決策和合約執行情況。',base:[200,10,25,15,50],shift:30,affected:3,charge:'留在經銷商的跌價損失',docs:[['經銷協議與補償條款','本案約定總部控制重大備貨與跌價風險，須按條件補償；日常倉儲作業由當地負責。','§1.60 · 契約風險'],['備貨指示與財務能力','總部具能力的供應鏈團隊實際下令追加備貨，並有事前資金與授信資料；當地執行出貨。','§1.64–1.66 · 控制與資力'],['跌價損失與補償帳務','例示跌價損失 30 全留在風車島，按約應有的補償未入帳。本情境假設金額及條件均已證實。','§1.86–1.106 · 實際行為及風險配置'],['企業提出的反證','總部主張部分損失源自當地倉儲疏失；應分離市場跌價與可歸責作業損失，不能以 LRD 名稱一概要求補償。','Ch. I、III · 分離風險來源']],issue:'損失是總部控制的跌價風險，還是當地倉儲疏失？補償是交易條款的一部分，還是事後保證獲利？',method:'本故事假設 30 全屬已證實應補償的跌價，故以補償金額例示調整；並未使用 LRD 固定利潤率。',amount:30,authority:'荷蘭稅務機關（概念模擬）',taxLabel:'外國調整概念 · 程序與稅率為假設，非荷蘭法定流程',resolution:'須釐清跌價及作業疏失各占多少，必要時修正補償金額。LRD 可能保留作業風險，不能只看虧損就自動調增至正利潤。',memory:'建立重大備貨審批、跌價及作業損失分流、補償執行勾稽；不把「有限風險」當作保證獲利標籤。'}
};
let sim={case:'manufacturing',stage:0,view:'macro',role:'observer',plan:'stress',docs:[],conclusion:null,playing:false,memory:[],cycle:1};let simTimer;
const stageNames=['策略規劃','生產與交易','損益與申報','風險選案','證據調查','擬議調整','爭議與演化'];
const agencyRoles={observer:'全知觀察者',company:'集團 TP 經理',inspector:'國稅局調查員'};
function profits(){const c=cases[sim.case],p=c.base.slice();if(sim.plan==='stress'&&sim.stage>=2){p[0]+=c.shift;p[c.affected]-=c.shift}return p}
function simNarrative(){const c=cases[sim.case],stress=sim.plan==='stress';return [
['🧑🏻‍💼 總部代理',stress?c.strategy:'集團決定先按故事的基準安排營運，保存各島決策與分部損益資料。','選擇營運安排，再推進時間。風險訊號不等於已證明避稅。'],
['👨🏻‍🔬 營運代理',c.business,c.counter],
['📒 財務代理',stress?`本期「${c.charge}」改變，例示 ${c.shift} 利潤由當地移往總部。集團合計仍為 300。`:'各島依基準情境申報，集團合計利潤 300；基準只是教學比較點，仍需證據支持常規結果。','切換宏觀分配與微觀公司檔案，觀察帳務與功能是否一致。'],
['🕵🏻 查核代理',stress?'申報、交易及功能出現值得調查的差異；發出資料請求，尚未作成不合常規認定。':'本期沒有策略性利潤變動訊號；仍以抽核情境檢視交易實質，不能把沒有訊號視為認證。','選案訊號是教學規則，並非稅局真實評分模型；低稅負或跨國交易本身不證明避稅。'],
['🔍 證據代理','企業說法與查核假說都需用文件驗證。請同時開啟支持證據與企業反證，再作初步判斷。',c.issue],
['⚖️ 審查代理',sim.conclusion==='adjust'&&stress?'依你採納的本案假設，提出擬議調整，供企業陳述與後續審查。':sim.conclusion==='noadjust'?'你選擇目前不調整：請保留理由，並檢視是否足以回應已知差異。':'你選擇補查或基準情境：目前不將差異直接轉成補稅結論。',c.method],
['🌱 學習代理','本輪經驗轉成下一輪的公司治理記憶。這是規則式狀態更新，不是模型訓練或自主法律判斷。',c.resolution]
][sim.stage]}
function paintSimulation(){const c=cases[sim.case],n=simNarrative(),p=profits();$('#simulation').innerHTML=`<div class="section-heading"><div><div class="eyebrow">LIVING TP CITY · RULE-BASED AGENT SIMULATION</div><h2>一座城市，七幕企業與查核故事。</h2></div><span class="season-pill">🎃 秋日特別篇</span></div><div class="sim-shell"><div class="sim-toolbar"><label>故事 <select id="sim-case">${Object.entries(cases).map(([k,v])=>`<option value="${k}" ${sim.case===k?'selected':''}>${v.label}</option>`).join('')}</select></label><label>你的角色 <select id="sim-role">${Object.entries(agencyRoles).map(([k,v])=>`<option value="${k}" ${sim.role===k?'selected':''}>${v}</option>`).join('')}</select></label><span class="sim-cycle">第 ${sim.cycle} 輪 · 第 ${sim.stage+1} 幕 / 7</span><button class="choice" id="sim-play">${sim.playing?'Ⅱ 暫停演出':'▷ 播放演出'}</button><button class="primary" id="sim-next" ${sim.stage===6?'disabled':''}>推進一幕 →</button></div><div class="sim-stages">${stageNames.map((s,i)=>`<span class="${i===sim.stage?'current':i<sim.stage?'past':''}"><b>${String(i+1).padStart(2,'0')}</b>${s}</span>`).join('')}</div><div class="sim-columns"><div class="sim-main"><div class="sim-view-tabs"><button id="macro-view" class="${sim.view==='macro'?'selected':''}">◎ 宏觀 · 全球分配</button><button id="micro-view" class="${sim.view==='micro'?'selected':''}">⌕ 微觀 · 公司檔案</button></div>${sim.view==='macro'?`<div class="structure"><b>100% 持股的集團架構</b><p>SG 森光總部持有 TW／JP／NL／US 子公司各 100%；本案具關係企業身分。持股不直接決定報酬。</p><span>交易結構：${c.flow}</span></div><table class="profit-table"><tr><th>公司</th><th>故事基準</th><th>本期利潤</th><th>變化</th></tr>${islands.map((o,i)=>`<tr class="${c.affected===i?'affected':''}"><td>${o.flag} ${o.country}<small>${o.role.split(' / ')[0]}</small></td><td>${c.base[i]}</td><td><b>${p[i]}</b></td><td class="${p[i]<c.base[i]?'negative':'positive'}">${p[i]-c.base[i]>0?'+':''}${p[i]-c.base[i]}</td></tr>`).join('')}<tr><th>集團合計</th><th>300</th><th>300</th><th>0</th></tr></table><p class="sim-fine">金額為無量綱教學單位；基準非已查得的實際可比較公司。集團合計不變，不表示各地分配符合常規。</p>`:microDossier(c,p)}<div class="sim-narrative"><span>${n[0]}</span><h3>${n[1]}</h3><p>${n[2]}</p></div>${sim.stage===0?`<div class="choice-row"><button class="choice ${sim.plan==='base'?'selected':''}" id="plan-base">基準營運安排</button><button class="choice ${sim.plan==='stress'?'selected':''}" id="plan-stress">爭議安排 · 觀察風險</button></div>`:''}${sim.stage===4?simEvidence(c):''}${sim.stage===5?simAdjustment(c):''}${sim.stage===6?simEvolution(c):''}</div><aside class="sim-agents"><div class="eyebrow">CITY AGENTS · 當前任務</div>${[['🧑🏻‍💼','總部','配置資源與回應調查',0],['👨🏻‍🔬','子公司','執行生產、研發或銷售',1],['📒','財務','勾稽分部及交易損益',2],['🕵🏻','稽徵機關','選案、蒐證與審查',3],['🌱','學習代理','記錄爭點、修正下一期',6]].map(([icon,name,task,step])=>`<div class="agent ${sim.stage===step||(step===3&&sim.stage>3&&sim.stage<6)?'active-agent':''}"><span>${icon}</span><div><b>${name}</b><small>${task}</small></div><i></i></div>`).join('')}<div class="role-lens"><b>${agencyRoles[sim.role]}的思考</b><p>${sim.role==='company'?c.business:sim.role==='inspector'?'先界定交易、蒐集正反證據，再檢驗方法與常規結果；不能由利潤低直接跳到補稅。':c.issue}</p></div><div class="sim-memory"><b>🌱 城市記憶 · ${sim.memory.length} 筆</b>${sim.memory.length?sim.memory.slice(-2).map(m=>`<p>${m}</p>`).join(''):'<p>完成本輪後，代理將保留治理改善與待查爭點，帶入下一輪。</p>'}</div><p class="sim-fine">模擬代理依預設情節與你的選擇更新。未串接外部 LLM；不是 AgentArk／HEART 的程式復刻。</p></aside></div><div class="sim-bottom"><span>參照 OECD TPG 2022 · Chapters ${c.chapter}</span><button id="sim-law">查核、補稅與救濟的依據 ↗</button><button id="sim-restart">↻ 重開本故事</button></div></div>`;
$('#sim-case').onchange=e=>{stopSim();sim.case=e.target.value;sim.stage=0;sim.docs=[];sim.conclusion=null;paintSimulation();selectIsland(cases[sim.case].island)};$('#sim-role').onchange=e=>{sim.role=e.target.value;paintSimulation()};$('#sim-next').onclick=advanceSim;$('#sim-play').onclick=toggleSim;$('#macro-view').onclick=()=>{sim.view='macro';paintSimulation()};$('#micro-view').onclick=()=>{sim.view='micro';paintSimulation()};$('#sim-restart').onclick=()=>{stopSim();sim.stage=0;sim.docs=[];sim.conclusion=null;paintSimulation()};$('#sim-law').onclick=showAuditLaw;
if(sim.stage===0){$('#plan-base').onclick=()=>{sim.plan='base';paintSimulation()};$('#plan-stress').onclick=()=>{sim.plan='stress';paintSimulation()}}if(sim.stage===4){document.querySelectorAll('[data-sim-doc]').forEach(el=>el.ontoggle=()=>{if(el.open&&!sim.docs.includes(+el.dataset.simDoc)){sim.docs.push(+el.dataset.simDoc);$('#evidence-count').textContent=sim.docs.length+' / 4';$('#decision-lock').textContent=sim.docs.length===4?'已查看四份資料，請選擇初步判斷。':'請先查看四份資料，包含企業反證。';if(sim.docs.length===4)document.querySelectorAll('[data-conclusion]').forEach(b=>b.disabled=false)}});document.querySelectorAll('[data-conclusion]').forEach(el=>el.onclick=()=>{sim.conclusion=el.dataset.conclusion;paintSimulation()})}if(sim.stage===5)wireSimTax();if(sim.stage===6)$('#next-cycle').onclick=()=>{sim.memory.push(`第 ${sim.cycle} 輪：${c.memory}${sim.conclusion==='more'?' 保留補查事項，不直接作成調整。':''}`);sim.cycle++;sim.stage=0;sim.plan='base';sim.docs=[];sim.conclusion=null;paintSimulation();toast('🌱 已帶入查核經驗，下一輪採基準安排。')};paintMapSignals()}
function microDossier(c,p){let o=islands[c.island];return `<div class="micro-dossier"><div class="country"><span class="flag">${o.flag}</span><div><h2>${o.name}</h2><small>由 SG 總部 100% 持有 · 本期利潤 ${p[c.island]}</small></div></div><div class="note"><b>生產／營運策略</b><br>${c.strategy}</div><table><tr><th>F 功能</th><td>${o.f}</td></tr><tr><th>A 資產</th><td>${o.a}</td></tr><tr><th>R 風險</th><td>${c.risk}</td></tr><tr><th>控制與承擔</th><td>需比較總部與當地的實際決策、人員能力、事前資力及結果承擔；請進入第五幕蒐證。</td></tr></table><p class="sim-fine">本輪爭點：${c.issue}</p></div>`}
function simEvidence(c){return `<h3>打開文件，聽見雙方說法 <small id="evidence-count">${sim.docs.length} / 4</small></h3>${c.docs.map((d,i)=>`<details class="evidence" data-sim-doc="${i}" ${sim.docs.includes(i)?'open':''}><summary>${d[0]}</summary><p>${d[1]}<br><small>閱讀連結：OECD ${d[2]}</small></p></details>`).join('')}<p id="decision-lock" class="sim-fine">${sim.docs.length===4?'已查看四份資料，請選擇初步判斷。':'請先查看四份資料，包含企業反證。'}</p><div class="choice-row">${[['adjust','依教學假設支持擬議調整'],['more','證據不足，先補查'],['noadjust','目前不調整，保留理由']].map(([k,t])=>`<button data-conclusion="${k}" class="choice ${sim.conclusion===k?'selected':''}" ${sim.docs.length<4?'disabled':''}>${t}</button>`).join('')}</div>${sim.conclusion?`<div class="feedback">${sim.conclusion==='adjust'?'調整仍需回應企業反證，並支持交易界定、方法與金額；不是看到風險就直接補稅。':sim.conclusion==='more'?'保留待查事項：實際控制者、反證可信度、差異調整及是否重複計酬。下幕以未定結論呈現。':'沒有調整也應有理由；若尚未回應分部差異及反證，應回到補查。你可以改選初步判斷。'}</div>`:''}`}
function simAdjustment(c){const apply=sim.conclusion==='adjust'&&sim.plan==='stress';return `<div class="note"><b>${apply?'擬議調增所得的算術實驗':'目前未作成調增所得結論'}</b><p>${c.taxLabel}。以下數字可修改以討論結果，並非系統認定的法定補稅。</p>${apply?`${sim.case==='manufacturing'?`<div class="form-grid"><label>一致成本基礎<input id="tax-base" type="number" min="0" value="1000"></label><label>例示淨利率（%）<input id="tax-target" type="number" step="0.1" value="5"></label><label>申報該交易淨利<input id="tax-reported" type="number" value="10"></label><label>假設稅率（%）<input id="tax-rate" type="number" min="0" max="100" value="20"></label></div>`:`<div class="form-grid"><label>例示調增所得<input id="tax-amount" type="number" min="0" value="${c.amount}"></label><label>假設稅率（%）<input id="tax-rate" type="number" min="0" max="100" value="20"></label></div>`}<div id="sim-tax-result" class="feedback" aria-live="polite"></div>`:'<p>將「疑似風險」、「補查中」、「擬議調整」與「核定補稅」分開；可回到本故事重新檢查證據。</p>'}<p class="sim-fine">簡化算法未計虧損扣抵、抵減、利息、其他稅目或罰鍰。罰鍰須另依要件審認，並非調整就自動處罰。</p></div>`}
function wireSimTax(){if(!$('#tax-rate'))return;function calc(){const rate=Number($('#tax-rate').value),base=$('#tax-base')?Number($('#tax-base').value):0,target=$('#tax-target')?Number($('#tax-target').value):0,reported=$('#tax-reported')?Number($('#tax-reported').value):0;let amount=$('#tax-amount')?Number($('#tax-amount').value):Math.max(0,base*target/100-reported);if([rate,base,target,reported,amount].some(v=>!Number.isFinite(v))||rate<0||rate>100||base<0||amount<0||target<0||target>100){$('#sim-tax-result').textContent='請確認輸入：成本與調增額非負，比率介於 0–100%。';return}$('#sim-tax-result').innerHTML=`擬議調增所得 <b>${amount.toLocaleString()}</b> × 假設稅率 ${rate}% ＝ 例示新增稅額 <b>${(amount*rate/100).toLocaleString()}</b>${$('#tax-base')?`<br><small>max(0, ${base} × ${target}% − ${reported}) ＝ ${amount}。本情境以可靠區間及中位數作假設，非一律採 5%。</small>`:''}<br><small>原始帳務尚未重編；單國所得調整不代表交易對方自動對應減少。</small>`}document.querySelectorAll('.simulation input').forEach(e=>e.oninput=calc);calc()}
function simEvolution(c){return `<div class="audit-flow"><h3>從擬議調整，到程序上的結果</h3><ol><li><b>告知差異與聽取說明</b>：企業提出反證，檢驗交易、方法與金額。</li><li><b>核准與核定</b>：臺灣一般 TP 情境依所得稅法第 43 條之 1 及查核準則辦理報核與核定，不能以 OECD 指引取代國內法。</li><li><b>補稅與處罰分開</b>：經核定通知後依適用規定處理繳納；是否處罰另依法定要件判斷。</li><li><b>救濟與雙重課稅</b>：依適用規定評估復查等國內救濟；跨境對應調整與 MAP 須有適用協定及程序支持，不自動發生，也不保證結果。</li><li><b>下一輪營運</b>：${c.memory}</li></ol></div><label class="reflection-label">留下你的爭點筆記（本輪暫存，不會送出）<textarea id="sim-reflection" rows="3" placeholder="例如：若總部提出真正的技術決策紀錄，原先的 DEMPE 結論會改變嗎？"></textarea></label><button class="primary" id="next-cycle">🌱 帶著經驗，啟動下一輪 →</button>`}
function advanceSim(){if(sim.stage===4&&(!sim.conclusion||sim.docs.length<4)){stopSim();paintSimulation();toast('請查看四份資料並選擇初步判斷，再推進。');return}if(sim.stage<6){sim.stage++;if(sim.stage===4||sim.stage===6)stopSim();paintSimulation();selectIsland(cases[sim.case].island)}}
function toggleSim(){if(sim.playing){stopSim();paintSimulation();return}if(sim.stage===6){toast('請先完成本輪或重新開始故事。');return}sim.playing=true;paintSimulation();simTimer=setInterval(()=>{advanceSim()},4500)}
function stopSim(){sim.playing=false;clearInterval(simTimer)}
function paintMapSignals(){let svg=$('#map-art svg');if(!svg)return;svg.querySelector('#city-signals')?.remove();const o=islands[cases[sim.case].island],p=profits();svg.insertAdjacentHTML('beforeend',`<g id="city-signals" pointer-events="none"><text x="82" y="425" font-size="24">🎃</text><text x="925" y="191" font-size="19">👻</text><g transform="translate(38 473)"><rect width="247" height="25" rx="12" fill="#fff9e5"/><text x="13" y="17" font-size="10" fill="#607d63">第 ${sim.cycle} 輪 · ${stageNames[sim.stage]} · 規則式代理演出</text></g><g transform="translate(${o.x-47} ${o.y-108})"><rect width="112" height="24" rx="12" fill="${sim.stage>=3&&sim.stage<=5?'#f5dfb4':'#f7f8de'}"/><text x="56" y="16" text-anchor="middle" font-size="10" fill="#57765c">${sim.stage>=3&&sim.stage<=5?'🔍 查核進行中':'✧ 本期利潤 '+p[cases[sim.case].island]}</text></g><g transform="translate(793 465)" class="tax-dock" role="button" pointer-events="all" tabindex="0" aria-label="進入國稅局查核流程"><rect x="-20" y="-21" width="174" height="33" rx="16" fill="#faf3dc"/><text font-size="11" fill="#597463">🏛 國稅局 · 查核與補稅流程 ↗</text></g></g>`);svg.querySelector('.tax-dock').onclick=showAuditLaw;svg.querySelector('.tax-dock').onkeydown=e=>{if(e.key==='Enter')showAuditLaw()}}
const originalDrawMap=drawMap;drawMap=function(){originalDrawMap();paintMapSignals()};
function showAuditLaw(){openModal('國稅局碼頭 · 查核與補稅流程',`<div class="eyebrow">EVIDENCE → ANALYSIS → ASSESSMENT</div><h2>🏛 看見風險後，還有一段查核旅程。</h2><p class="lead">本碼頭呈現臺灣一般 TP 案的概念流程；外國公司案例只模擬 OECD 分析，不套用臺灣程序。具體案件仍依適用年度、法令及協定辦理。</p><table><tr><th>階段</th><th>玩家要處理的問題</th></tr><tr><td>選案與資料請求</td><td>辨認受控交易、分部差異及需要補充的證據。訊號不等於違法。</td></tr><tr><td>交易界定與比較分析</td><td>檢視實際 FAR、方法、可比較對象與可靠調整，回應企業說明。</td></tr><tr><td>報核與核定</td><td>一般情境依所得稅法第 43 條之 1 報經財政部核准按常規調整；依查核準則核定所得。</td></tr><tr><td>稅額與罰鍰</td><td>調增所得再計算稅額；罰鍰須另外審認查核準則第 34 條及相關法律要件。</td></tr><tr><td>救濟與跨境處理</td><td>依適用規定評估復查等救濟。跨境對應調整與 MAP 須另檢查適用協定及條件。</td></tr></table><div class="note">OECD TPG 是分析依據，不是臺灣補稅程序的直接法源。第 35 條規定的境內相對調整，不應直接當成外國必須自動調減的依據。</div><div class="citation">臺灣法源：<a href="https://law-out.mof.gov.tw/LawContent.aspx?id=FL005935" target="_blank" rel="noopener">所得稅法第 43 條之 1 ↗</a>；<a href="https://law.moj.gov.tw/LawClass/LawAll.aspx?PCode=G0340019" target="_blank" rel="noopener">TP 查核準則第 2、33–35 條 ↗</a><br>國際分析：<a href="${OECD}" target="_blank" rel="noopener">OECD TPG 2022 第 I–VI、IX 章 ↗</a>。本站法源查閱日期：2026-10-28。</div>`)}
document.querySelector('[data-nav="sim"]').onclick=()=>{$('#modal').close();$('#simulation').scrollIntoView({behavior:'smooth',block:'start'})};
$('#mobile-island').onchange=e=>selectIsland(+e.target.value);
paintSimulation();
